/** Bumped whenever any template's output changes — it is part of every manifest digest. */
export const WEB_EMITTER_VERSION = "2.0.0";

/** `// <subject> — generated by @codai/axiom-emitters-web (web@<version>).` */
export function generatedBanner(subject: string): string {
  return `// ${subject} — generated by @codai/axiom-emitters-web (web@${WEB_EMITTER_VERSION}).`;
}
